import{_ as o,c as t,aU as c,a}from"./chunks/framework.DIXiA2XH.js";const d="/assets/%E7%81%AB.EnAycDqG.jpeg",b=JSON.parse('{"title":"about me","description":"","frontmatter":{},"headers":[],"relativePath":"about/me.md","filePath":"about/me.md","lastUpdated":1772203450000}'),r={name:"about/me.md"};function l(p,e,s,i,n,m){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="about-me" tabindex="-1">about me <a class="header-anchor" href="#about-me" aria-label="Permalink to &quot;about me&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">共勉</p><p>种一棵树最好的时间是十年前，其次是现在。</p></div><p>恭喜你，发现一名宝藏博主</p><p>大家好，我是敲代码的卡卡罗特，<code>站长</code>/<code>博主</code>/<code>程序猿</code>/<code>健身爱好者</code>/<code>不知名up主</code>/<code>各大论坛潜水员</code>...</p><p>老家河南，目前在杭州干 <s><code>JAVA后端开发</code></s> Go开发、回到家<code>全栈开发</code>，目标是以后做一个可以养活自己的<code>独立开发者</code></p><p>我自认为是一个 <code>好学</code>，<code>自律</code>，<code>靠谱</code>，<code>热血</code>，<code>努力</code>，<code>低调幽默</code>，<code>喜欢研究一些乱七八糟好玩的东西</code>，<code>对一切有趣的事物都感兴趣</code>... 的程序猿</p><p>日常除了写代码之外，就是在网上乱逛，论坛，博客啥的，看看新闻，电影，听歌，刷抖音，打几局斗地主，把每天送的低保5k豆输完结束，或者偶尔下两盘象棋， 一直处于新手水平。当然健身也是必不可少的，虽然现在很<a href="/note/sport/我的健身日记.html">辣鸡</a>，连引体还没拉明白，但是我相信我一定会解锁双力臂。</p><p>可能大家访问的时候可能会感觉有点点点慢，那是因为服务器部署在国外服务器 <code>Vercel</code> 上面，虽然我有也有阿里云的服务器，没办法它的自动化做的实在是太方便了，博客我基本上每天都需要发布， 所以每次打包上传太麻烦了，我又不想在服务器上搭一套环境，麻烦，等我有空看看有什么免费的cdn加上吧。不过我的 <a href="https://tool.share888.top/" target="_blank" rel="noreferrer">程序猿必备工具网站</a>部署在了阿里云上面，起初我也是一样 部署到<code>Vercel</code>上的，不过工具这玩意我是天天用的，有时候确实是给我慢的急死，索性就放到国内服务器了，反正基本上不加新功能的话是不会发布它。</p><p>用了很多博客平台（csdn，51cto,博客园，掘金，知乎，简书，sf,有道云，语雀，wordpress），最终还是选择了自建博客平台来写文章，1是不想看到 辛辛苦苦写的文章，最后给我来一个审核不通过。2是结识更多优秀的人</p><p>这个博客我会一直经营下去，不会出现断更的情况。关注我你会得到：</p><ol><li>我看过的好的电影，电视剧，和歌曲，动漫</li><li>我买过的比较实用的东西,测评</li><li>在工作中或者在做独立开发的过程所遇到的bug以及解决方案</li><li>分享一些好用的<a href="https://software.share888.top/" target="_blank" rel="noreferrer">开发工具软件，windows必备工具</a>等</li><li>开发常用的代码工具类</li><li>非常非常非常实用的导航，我每天都在用，都是精品中的精品！</li><li>非常有意思的黑科技</li><li>...</li></ol><p>一直在探索副业之路，但是都没什么起色。虽然没什么进展，但是</p><p><img src="'+d+'" alt=""></p>',13)])])}const f=o(r,[["render",l]]);export{b as __pageData,f as default};
